// agent took on records that judgment under v2, "issue: true", as the old engine read it from the prompt)
const ISSUE_LINE = 'Issue: the complaint in this request | runbook: learn-from-upset | fixed when: the miss is fixed and its lesson written\n';
function runStop(s0) {
  if (s0.issue) s0 = { ...s0, files: { ...(s0.files || {}), '.cache/turn-notes.md': ISSUE_LINE + ((s0.files || {})['.cache/turn-notes.md'] || '') } };
  // (the shared Finished line names docs/x.md; under v2 a claimed file that is not there is held (rule 4, triage: settled),
  // so a scenario using it gets that file, dated before the turn so it is no work of the turn. A scenario's own claim
  // of a file that is not there is still held)
  // (the answer may come from the host's last message only: the same file then)
  if (process.env.STARTER_ENGINE === 'v2' && String(s0.answer || s0.last || '').includes(FIN) && !(s0.files || {})['docs/x.md'])
    s0 = { ...s0, files: { ...(s0.files || {}), 'docs/x.md': '# x\n' }, mtimes: { ...(s0.mtimes || {}), 'docs/x.md': -3_600_000 } };
  // (a fixture file is written after the turn starts, so the old engine counts it as this turn's work. v2 counts a file
  // only when a call of the turn wrote it (a file changed with no writer is another session's), so under v2 each fixture
  // file no call names gets the Write that made it, unless its time is set back to before the turn ("mtimes"). Lesson
  // (the old suite under v2): tests whose work was only fixture files read as turns that changed nothing)
  // (not a file git ignores, such as build output, nor one already there with the same content: neither is a change
  // under the old engine either)
  let s = s0;
  const dir = takeCopy(!!s.own);
  try {
    if (!s.own) ownChecksOff(dir);
    const since = Date.now() - 1000;
    if (s.usage) write(dir, { 'tools/hooks/state/runbook-usage.json': JSON.stringify(s.usage) });
    if (s.removeMarker) fs.rmSync(path.join(dir, '.starter-template'), { force: true }); // a project, not the starter
    applyEdits(dir, s.edit, since - 3600_000);
    if (s.prep) s.prep(dir, since);
    // (a scenario with a command or a helper keeps its files on that path: a command may have written them, and the run
    // window and writer rule are what such a scenario tests. Lesson (a peer's review): a synthetic Write would hide it)
    if (process.env.STARTER_ENGINE === 'v2' && !(s0.tools || []).some(t => /^(Bash|PowerShell|Agent|Task)$/.test(t.name))) {
      const named = new Set(JSON.stringify(s0.tools || []).match(/[\w./-]+\.\w+/g) || []);
      const same = p => { try { return fs.readFileSync(path.join(dir, p), 'utf8') === String(s0.files[p]); } catch { return false; } };
      const ignored = p => spawnSync('git', ['check-ignore', '-q', '--no-index', p], { cwd: ROOT }).status === 0; // (the fixture copy has no git: the starter's own ignore rules, which it carries)
      // (a file whose time the scenario sets says itself when it changed and by whom, before the turn or by the user during
      // it: never the turn's own write)
      // (a file the scenario sets to undefined is one the turn did not write: it gets no Write call. Lesson (the old suite
      // under v2): "docs/CHANGELOG.md": undefined read as a changelog written, so a missing one was never held)
      const wrote = Object.keys(s0.files || {}).filter(p => s0.files[p] !== undefined && !named.has(p) && !(p in (s0.mtimes || {})) && !/^(\.cache|tools\/hooks\/state)\//.test(p) && !same(p) && !ignored(p));
      // (written first, with the fixture's own content, as the work the scenario's calls then test or review: a stub edit
      // after them read as code changed after its tests ran and hid the content the security check reads)
      if (wrote.length) s = { ...s0, tools: [...wrote.map(p => ({ name: 'Write', input: { file_path: p, content: String(s0.files[p]) } })), ...(s0.tools || [])] };
    }
    const tp = transcript(dir, s, since);
    // the fixture's transcript sits in the project (a real one lives outside it): it was there before the turn
    const sp = path.join(dir, 'tools/hooks/state/snapshot.json');
    if (fs.existsSync(sp)) { try { const j = JSON.parse(fs.readFileSync(sp, 'utf8')); j.files['transcript.jsonl'] = [0, 0, null]; fs.writeFileSync(sp, JSON.stringify(j)); } catch { } }
    if (s.blocks || s.waitBlocks) write(dir, { 'tools/hooks/state/stop-blocks.json': JSON.stringify({ [`${tp}|${since}`]: s.blocks || 0, ...(s.waitBlocks ? { [`${tp}|${since}|wait`]: s.waitBlocks } : {}) }) });
    if (s.failed) write(dir, { 'tools/hooks/state/stop-failed.json': JSON.stringify({ key: `${tp}|${since}`, tags: s.failed, ...(s.failedExtra || {}) }) });
    // (turnEnd: this request already ended cleanly once, with this record, e.g. the answer it ended with)
    if (s.turnEnd) write(dir, { 'tools/hooks/state/turn-end.json': JSON.stringify({ at: new Date().toISOString(), key: `${tp}|${since}`, clean: true, ...s.turnEnd }) });
    // (a real session's prompt hook records when the turn started, so its Stop regenerates skills and DIRECTORY.md from a
    // runbook the turn changed. Here the last sync is dated just before the scenario's own files, its turn's changes.
    // Lesson: with neither, v2 synced nothing and a new runbook never got its skill)
    if (process.env.STARTER_ENGINE === 'v2' && !fs.existsSync(path.join(dir, 'tools/hooks/state/synced-at.json'))) {
      write(dir, { 'tools/hooks/state/synced-at.json': '{}' }); const t0 = (Date.now() - 20) / 1000; fs.utimesSync(path.join(dir, 'tools/hooks/state/synced-at.json'), t0, t0);
    }
    write(dir, s.files);
    for (const [p, off] of Object.entries(s.mtimes || {})) { const t = (Date.now() + off) / 1000; fs.utimesSync(path.join(dir, p), t, t); }
    // (under v2 each scenario has a session, so its Stop decision is logged and a failing scenario says which way it went:
    // judged and passed, waiting on a background run, or ended early. Lesson: an intermittent wrong pass left no trace)
    const V2SID = process.env.STARTER_ENGINE === 'v2' ? { session_id: 'scenario' } : {};
    // (the fixtures' Finished section names docs/x.md; v2 checks that a named file exists, the old engine did not: the
    // file is there, from before the turn, unless the scenario is about it)
    if (V2SID.session_id && [s.answer, ...(s.drafts || [])].some(t => String(t || '').includes('docs/x.md')) && !fs.existsSync(path.join(dir, 'docs/x.md'))) {
      write(dir, { 'docs/x.md': '# x\n' }); const old = (since - 3600_000) / 1000; fs.utimesSync(path.join(dir, 'docs/x.md'), old, old);
    }
    // (a repeat round, under v2, is the turn v2 recorded as blocked already: without that record v2 lets the Stop end
    // unjudged, and a scenario expecting a pass passed by not running. Oversight, 2026-11-10)
    // (a turn the prompt hook recorded in the scenario's prep is the same turn: it gets the repeat round's marks)
    const v2tf = path.join(dir, 'tools/hooks/state/v2-turn.scenario.json');
    if (V2SID.session_id && s.active && s.prep && !(s.hookInput || {}).session_id && fs.existsSync(v2tf)) {
      const t = JSON.parse(fs.readFileSync(v2tf, 'utf8'));
      if (!t.blocked) fs.writeFileSync(v2tf, JSON.stringify({ ...t, blocked: t.at, rounds: ((s.blocks || 0) + (s.waitBlocks || 0)) || 1 }));
    }
    if (V2SID.session_id && s.active && !(s.hookInput || {}).session_id && !fs.existsSync(path.join(dir, 'tools/hooks/state/v2-turn.scenario.json'))) {
      const at0 = new Date(since).toISOString();
      // (blocks made while waiting on helpers count toward the cap too, as the old engine counted them)
      write(dir, { 'tools/hooks/state/v2-turn.scenario.json': JSON.stringify({ at: at0, runbook: null, blocked: at0, rounds: ((s.blocks || 0) + (s.waitBlocks || 0)) || 1 }) });
      // (the checks that held the earlier round, as v2 logs them: the steps it showed, in its Stop log)
      const V2_STEP = { 'rule-request': 'Write the rule down: node tools/hooks/hooks.mjs rule', 'rule-memory': 'Save the rule to memory too', 'upset-learned': 'Write the lesson where it stops the next miss', 'hooks-tested': 'The hook logic changed: run node tools/hooks/selfcheck.mjs' };
      const steps = (s.failed || []).map(t => ENGINE_MSG[t] ? `Check: ${ENGINE_MSG[t]}` : V2_STEP[t]).filter(Boolean).map(x => x.replace(/\s+/g, ' ').slice(0, 80));
      if (steps.length) write(dir, { 'tools/hooks/state/stop-log.jsonl': JSON.stringify({ at: at0, session: 'scenario', request: at0, round: 1, result: 'blocked', steps }) + '\n' });
    }
    const { out, err } = run(dir, 'stop', { transcript_path: tp, stop_hook_active: !!s.active, ...V2SID, ...(s.last ? { last_assistant_message: s.last } : {}), ...(s.hookInput || {}) }, s.host);
    let decision = ''; try { decision = fs.readFileSync(path.join(dir, 'tools/hooks/state/stop-log.jsonl'), 'utf8').trim().split('\n').pop() || ''; } catch { }
    let d = null; try { d = out.trim() ? JSON.parse(out) : null; } catch { }
    // either form asks for more work: the classic block, or the calm feedback form (stopStyle)
    // (v2's short text stands for the full steps in tools/hooks/state/stop-details.md: the scenarios judge those)
    const reason = v2Full(dir, d);
    const after = s.after ? s.after(dir, reason, d) : true;
    // the full steps behind the short message (hooks.mjs why)
    let details = ''; try { details = fs.readFileSync(detailsPath(dir), 'utf8'); } catch { }
    return { blocked: !!(d && (d.decision === 'block' || d.hookSpecificOutput?.additionalContext)), reason, details, err, after, decision };
  } finally { giveBack(dir, !!s.own); }
}

