// Zero drip-feed. stop-follow-on: what a step's fix sets off (the audit after a runbook, skill or rules edit, the hook
// self-tests after a checks edit, a data check after a data edit) is named in the same round as the step.
// skill-learn: a runbook matched by mistake gets no lesson. answer-resent: an unchanged answer may end with one line.
const MEAL_LESSON = NEWPB.replace('1. a\n', '1. a\n2. Say in the answer that the meals are planned.\n');
// a check keyed on the request that applies only once files change (preview: "If it changes files", not "held to")
const CATALOG_NOTED = (() => {
  const a = { tag: 'catalog-noted', when: { promptMatches: '\\bupdate the catalog\\b', filesChanged: ['data/**'] }, require: { filesChanged: ['docs/catalog-notes.md'] }, message: 'Note the catalog change in docs/catalog-notes.md.' };
  SCENARIO_TAGS.add(a.tag);
  return { 'tools/hooks/requirements.json': s => JSON.stringify({ requirements: [...JSON.parse(s).requirements, a] }) };
})();
const CATALOG_REQS = (() => {
  const a = { tag: 'catalog-updated', when: { promptMatches: '\\b(update the catalog|actualiza el catalogo)\\b' }, require: { filesChanged: ['data/**'] }, message: 'Write the catalog changes into data/.' };
  const b = { tag: 'data-valid', when: { filesChanged: ['data/**'] }, require: { toolPassed: { cmd: 'validate', pass: 'RESULT: PASS' } }, message: 'Run the validator until it passes.' };
  SCENARIO_TAGS.add(a.tag); SCENARIO_TAGS.add(b.tag);
  return { 'tools/hooks/requirements.json': s => JSON.stringify({ requirements: [...JSON.parse(s).requirements, a, b] }) };
})();
// (under v2 the same catalog check starts from what the turn did, its catalog notes, not the request's words: v2 starts
// no check from prompt words alone (keyword forcing retired 2026-11-07). Same follow-on: data/ written sets off the validator)
