    const env = { ...process.env, STARTER_MEMORY_DIR: path.join(dir, '.memtest') };
    for (const k of Object.keys(env)) if (/SESSION_ID$|^CLAUDE_CODE_ENTRYPOINT$|^CLAUDECODE$/.test(k)) delete env[k];
