    run(dir, 'stop', { transcript_path: tp, session_id: 'log1', stop_hook_active: true, last_assistant_message: 'Added it.' });
    const rows = (() => { try { return JSON.parse(nodeIn('last', '5', '--json').stdout); } catch { return []; } })(), text = nodeIn('last', '5').stdout;
